import type { ReactNode } from "react";
import "./editorial-shutter.css";

interface EditorialShutterProps {
  className?: string;
  /** Decorative, non-interactive media only; rendered inert and aria-hidden. */
  decorativeMedia: ReactNode;
  edge?: "left" | "right";
}

export function EditorialShutter({
  className = "",
  decorativeMedia,
  edge = "left",
}: EditorialShutterProps) {
  return (
    <div
      className={`tb-editorial-shutter ${className}`.trim()}
      data-edge={edge}
    >
      <div
        className="tb-editorial-shutter__frame"
        aria-hidden="true"
        inert
      >
        {decorativeMedia}
      </div>
    </div>
  );
}

.tb-editorial-shutter {
  position: relative;
  overflow: hidden;
}

.tb-editorial-shutter__frame {
  width: 100%;
  height: 100%;
  clip-path: inset(0);
  transition: clip-path 380ms cubic-bezier(0.16, 1, 0.3, 1);
}

@starting-style {
  .tb-editorial-shutter__frame {
    clip-path: inset(0 100% 0 0);
  }

  .tb-editorial-shutter[data-edge="right"] .tb-editorial-shutter__frame {
    clip-path: inset(0 0 0 100%);
  }
}

@media (prefers-reduced-motion: reduce) {
  .tb-editorial-shutter__frame {
    clip-path: inset(0);
    transition: none;
  }
}

@media (forced-colors: active) {
  .tb-editorial-shutter__frame {
    clip-path: none;
  }
}
